285	    /**
286	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
287	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
288	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
289	     * elapsed from the birth date to the registration date (defaulting to the server's current date
290	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
291	     *
292	     * @return the age band, or {@code null} when the birth date is absent
293	     */
294	    public String getAgeBand() {
295	        if (this.birthDate == null) {
296	            return null;
297	        }
298	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
299	        int years = Period.between(this.birthDate, asAt).getYears();
300	        if (years < 18) {
301	            return "MINOR";
302	        }
303	        if (years < 65) {
304	            return "ADULT";
305	        }
306	        return "SENIOR";
307	    }
