317	    /**
318	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
319	     * the last two digits of the {@link #getFiscalYear() fiscal year} of the registration date
320	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own customer code and registration
321	     * date; {@code null} when either is absent.
322	     *
323	     * @return the membership number, or {@code null} when it cannot be derived
324	     */
325	    public String getMembershipNumber() {
326	        if (this.customerCode == null || this.registrationDate == null) {
327	            return null;
328	        }
329	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
330	    }
331	
332	    /**
333	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
334	     * the fiscal year of the {@link #getRegistrationDate() business-day-adjusted registration date}.
335	     * The fiscal year starts on 1 July and is named by the calendar year in which it ends, so a
336	     * registration date on or after 1 July belongs to the following calendar year's fiscal year
337	     * (e.g. {@code 2026-07-01} is {@code 'FY27'}) while an earlier date stays in the current one
338	     * (e.g. {@code 2026-06-15} is {@code 'FY26'}). Returns {@code null} when the registration date is
339	     * absent.
340	     *
341	     * @return the fiscal year, or {@code null} when the registration date is absent
342	     */
343	    public String getFiscalYear() {
344	        if (this.registrationDate == null) {
345	            return null;
346	        }
347	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
348	    }
349	
350	    /**
351	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
352	     * is named by the calendar year in which it ends: a date in July through December belongs to the
353	     * next calendar year's fiscal year, while January through June stays in the current one.
354	     *
355	     * @param date the date to classify
356	     * @return the fiscal year as a four-digit calendar year
357	     */
358	    private static int fiscalYearOf(LocalDate date) {
359	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
360	    }
361	
362	    /**
363	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
364	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
365	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
366	     *
367	     * @return the Luhn check digit, or {@code null} when the customer code is absent
368	     */
369	    public Integer getCheckDigit() {
370	        if (this.customerCode == null) {
371	            return null;
372	        }
373	        int sum = 0;
374	        boolean dbl = true;
375	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
376	            char c = this.customerCode.charAt(i);
377	            if (c < '0' || c > '9') {
378	                continue;
379	            }
380	            int d = c - '0';
381	            if (dbl) {
382	                d *= 2;
383	                if (d > 9) {
384	                    d -= 9;
385	                }
386	            }
387	            sum += d;
388	            dbl = !dbl;
389	        }
390	        return (10 - (sum % 10)) % 10;
391	    }
392	
393	    /**
394	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
395	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
396	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
397	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
398	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
399	     * tenure, the tenure points are never awarded at create time.
400	     *
401	     * @return the membership points, a non-negative integer
402	     */
403	    public Integer getMembershipPoints() {
404	        int points = 0;
405	        boolean hasEmail = this.email != null && !this.email.isBlank();
406	        if (hasEmail) {
407	            points += 2;
408	        }
409	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
410	        if (hasNoNamesakes) {
411	            points += 1;
412	        }
413	        if (this.householdSize != null && this.householdSize >= 3) {
414	            points += 2;
415	        }
416	        Long tenureFiscalYears = getTenureFiscalYears();
417	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
418	            points += 3;
419	        }
420	        return points;
421	    }
422	
423	    /**
424	     * The owner's numeric membership level. This is normally derived from the
425	     * {@link #getMembershipPoints() membership points} (see {@link #deriveMembershipLevel()}), but a
426	     * household-level cap applied at create time may store a lower value here; when such a capped level
427	     * has been stored it is returned in preference to the derived one.
428	     *
429	     * @return the membership level, an integer from 1 to 4
430	     */
431	    public Integer getMembershipLevel() {
432	        if (this.membershipLevel != null) {
433	            return this.membershipLevel;
434	        }
435	        return deriveMembershipLevel();
436	    }
437	
438	    public void setMembershipLevel(Integer membershipLevel) {
439	        this.membershipLevel = membershipLevel;
440	    }
441	
442	    /**
443	     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
444	     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
445	     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
446	     *
447	     * @return the derived membership level, an integer from 1 to 4
448	     */
449	    public Integer deriveMembershipLevel() {
450	        int points = getMembershipPoints();
451	        if (points <= 1) {
452	            return 1;
453	        }
454	        if (points <= 3) {
455	            return 2;
456	        }
457	        if (points <= 5) {
458	            return 3;
459	        }
460	        return 4;
461	    }
462	
463	    /**
464	     * The owner's tenure in elapsed fiscal years, the number of fiscal-year boundaries crossed from
465	     * the {@link #getFiscalYear() fiscal year} of the {@link #getRegistrationDate() registration date}
466	     * to the fiscal year of the server's current date (the fiscal year starts on 1 July). An owner
467	     * registered in the current fiscal year has a tenure of 0; one elapsed fiscal year or more is what
468	     * awards the tenure membership points. Returns {@code null} when no registration date has been set
469	     * yet.
470	     *
471	     * @return the tenure in elapsed fiscal years, or {@code null} when the registration date is absent
472	     */
473	    public Long getTenureFiscalYears() {
474	        if (this.registrationDate == null) {
475	            return null;
476	        }
477	        return (long) (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
478	    }
479	
480	    /**
481	     * The owner's locality, the canonical region string. Once the owner has a
482	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
483	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
484	     * source of truth. Before the customer code is assigned (for example while a create is still
485	     * validating the postcode) it falls back to the region the code will be built from: the
486	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
487	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
488	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
489	     *
490	     * @return the canonical region string, or {@code 'UNKNOWN'}
491	     */
492	    public String getLocality() {
493	        if (this.customerCode != null) {
494	            int dash = this.customerCode.indexOf('-');
495	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
496	        }
497	        return deriveRegion();
498	    }
499	
500	    /**
501	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
502	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
503	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
504	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
505	     *
506	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
507	     */
508	    public String getTimezone() {
509	        return REGION_TIMEZONE.get(getLocality());
510	    }
511	
512	    /**
513	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
514	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER}
515	     * is {@code 'PREMIUM'} when the {@link #getMembershipLevel() membership level} is 3 or more,
516	     * otherwise {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the {@link #getLocality()
517	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
518	     *
519	     * @return the owner segment string
520	     */
521	    public String getOwnerSegment() {
522	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
523	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
524	        return tier + "_" + area;
525	    }
526	
527	    /**
528	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
529	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
530	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
531	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
532	     * the same region for known cities but disambiguates cities that share a name.
533	     *
534	     * @return the canonical region string, or {@code 'UNKNOWN'}
535	     */
536	    private String deriveRegion() {
537	        String region = regionFromPostcode();
538	        if (region != null) {
539	            return region;
540	        }
541	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
542	    }
543	
544	    /**
545	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
546	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
547	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
548	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
549	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
550	     * owner's region, telephone and last name. Call this once at create time and store the result via
551	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
552	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
553	     *
554	     * @return the assembled customer code
555	     */
556	    public String buildCustomerCode() {
557	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
558	    }
559	
560	    /**
561	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
562	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
563	     *
564	     * @param value the value to hash
565	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
566	     */
567	    private static String sha256Hex8(String value) {
568	        try {
569	            byte[] digest = MessageDigest.getInstance("SHA-256")
570	                .digest(value.getBytes(StandardCharsets.UTF_8));
571	            StringBuilder hex = new StringBuilder(8);
572	            for (int i = 0; i < 4; i++) {
573	                hex.append(String.format("%02X", digest[i]));
574	            }
575	            return hex.toString();
576	        }
577	        catch (NoSuchAlgorithmException e) {
578	            throw new IllegalStateException("SHA-256 algorithm not available", e);
579	        }
580	    }
581	
582	    /**
583	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
584	     * absent, not a 4-digit number, or in no known range.
585	     *
586	     * @return the matching region, or {@code null}
587	     */
588	    private String regionFromPostcode() {
589	        if (this.postcode == null) {
590	            return null;
591	        }
592	        int value;
593	        try {
594	            value = Integer.parseInt(this.postcode.trim());
595	        }
596	        catch (NumberFormatException ex) {
597	            return null;
598	        }
599	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
600	            int[] range = entry.getValue();
601	            if (value >= range[0] && value <= range[1]) {
602	                return entry.getKey();
603	            }
604	        }
605	        return null;
606	    }
607	
608	    /**
609	     * The owner's preferred contact channel, derived from the owner's details. Returns
610	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
611	     *
612	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
613	     */
614	    public String getContactPreference() {
615	        boolean hasEmail = this.email != null && !this.email.isBlank();
616	        return hasEmail ? "EMAIL" : "PHONE";
617	    }
618	
619	    /**
620	     * The owner's identity key, the single derived value used for duplicate detection. It is the
621	     * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
622	     * email (empty when absent) and the {@linkplain Soundex#encode(String) Soundex} of its last name,
623	     * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
624	     * absent ({@code null}) component contributes an empty string before hashing. Two owners are
625	     * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
626	     * (and its Soundex) and postcode but carrying different telephones differ here and are both
627	     * allowed (the second is flagged a soft match rather than rejected).
628	     *
629	     * @return the derived identity key, a 64-character lower-case hex string
630	     */
631	    public String getIdentityKey() {
632	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
633	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
634	        String raw = normalizedTelephone + "|" + lowerEmail + "|" + Soundex.encode(this.getLastName());
635	        return sha256HexLower(raw);
636	    }
637	
638	    /**
639	     * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
640	     * form the {@linkplain #getIdentityKey() identity key} takes.
641	     *
642	     * @param value the value to hash
643	     * @return the 64-character lower-case hex SHA-256 digest
644	     */
645	    private static String sha256HexLower(String value) {
646	        try {
647	            byte[] digest = MessageDigest.getInstance("SHA-256")
648	                .digest(value.getBytes(StandardCharsets.UTF_8));
649	            StringBuilder hex = new StringBuilder(digest.length * 2);
650	            for (byte b : digest) {
651	                hex.append(String.format("%02x", b));
652	            }
653	            return hex.toString();
654	        }
655	        catch (NoSuchAlgorithmException e) {
656	            throw new IllegalStateException("SHA-256 algorithm not available", e);
657	        }
658	    }
659	
660	    public String getHouseholdId() {
661	        return this.householdId;
662	    }
663	
664	    public void setHouseholdId(String householdId) {
665	        this.householdId = householdId;
666	    }
