708	    public Boolean getPossibleDuplicate() {
709	        return this.possibleDuplicate;
710	    }
711	
712	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
713	        this.possibleDuplicate = possibleDuplicate;
714	    }
715	
716	    public Integer getPossibleDuplicateOf() {
717	        return this.possibleDuplicateOf;
718	    }
719	
720	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
721	        this.possibleDuplicateOf = possibleDuplicateOf;
722	    }
723	
724	    /**
725	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
726	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
727	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
728	     *
729	     * @return whether the owner has been soft-deleted
730	     */
731	    public boolean isDeleted() {
732	        return this.deleted;
733	    }
734	
735	    public void setDeleted(boolean deleted) {
736	        this.deleted = deleted;
737	    }
738	
739	    /**
740	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
741	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
742	     */
743	    @PrePersist
744	    void onCreate() {
745	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
746	    }
747	
748	    /**
749	     * Resolves the effective registration date and rolls it onto a business day. An absent
750	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
751	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
752	     * holiday: starting from the effective date, the date advances one day at a time while it lands
753	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
754	     * non-holiday business day. A date already on a business day is returned unchanged.
755	     *
756	     * <p>This is the single definition of both the defaulting and the business-day roll, used
757	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
758	     * stamps the owner and by the create endpoint that counts owners per business day.
759	     *
760	     * @param supplied the registration date from the request, or {@code null} when none was supplied
761	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
762	     */
763	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
764	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
765	        while (!isBusinessDay(effective)) {
766	            effective = effective.plusDays(1);
767	        }
768	        return effective;
769	    }
770	
771	    /**
772	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
773	     */
774	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
775	        LocalDate.of(2026, 1, 1),
776	        LocalDate.of(2026, 1, 26),
777	        LocalDate.of(2026, 4, 25),
778	        LocalDate.of(2026, 12, 25),
779	        LocalDate.of(2026, 12, 28));
780	
781	    /**
782	     * A business day is any date that is neither a weekend day nor a listed public holiday.
783	     */
784	    private static boolean isBusinessDay(LocalDate date) {
785	        DayOfWeek day = date.getDayOfWeek();
786	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
787	    }
788	
789	    protected Set<Pet> getPetsInternal() {
790	        if (this.pets == null) {
791	            this.pets = new HashSet<>();
792	        }
793	        return this.pets;
794	    }
795	
796	    protected void setPetsInternal(Set<Pet> pets) {
797	        this.pets = pets;
798	    }
