800	    public List<Pet> getPets() {
801	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
802	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
803	        return Collections.unmodifiableList(sortedPets);
804	    }
805	
806	    public void setPets(List<Pet> pets) {
807	        this.pets = new HashSet<>(pets);
808	    }
809	
810	    public void addPet(Pet pet) {
811	        getPetsInternal().add(pet);
812	        pet.setOwner(this);
813	    }
814	
815	    /**
816	     * Return the Pet with the given name, or null if none found for this Owner.
817	     *
818	     * @param name to test
819	     * @return true if pet name is already in use
820	     */
821	    public Pet getPet(String name) {
822	        return getPet(name, false);
823	    }
824	
825	    /**
826	     * Return the Pet with the given name, or null if none found for this Owner.
827	     *
828	     * @param name to test
829	     * @return true if pet name is already in use
830	     */
831	    public Pet getPet(String name, boolean ignoreNew) {
832	        name = name.toLowerCase();
833	        for (Pet pet : getPetsInternal()) {
834	            if (!ignoreNew || !pet.isNew()) {
835	                String compName = pet.getName();
836	                compName = compName.toLowerCase();
837	                if (compName.equals(name)) {
838	                    return pet;
839	                }
840	            }
841	        }
842	        return null;
843	    }
844	
845	    public Pet getPet(Integer petId) {
846	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
847	    }
848	
849	    @Override
850	    public String toString() {
851	        return new ToStringCreator(this)
852	
853	            .append("id", this.getId())
854	            .append("new", this.isNew())
855	            .append("lastName", this.getLastName())
856	            .append("firstName", this.getFirstName())
857	            .append("address", this.address)
858	            .append("city", this.city)
859	            .append("telephone", this.telephone)
860	            .toString();
861	    }
862	}
