309	     * @param ownerId the created owner's id
310	     * @param customerCode the owner's current primary identifier
311	     * @param membershipLevel the owner's membership level
312	     */
313	    private record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode, Integer membershipLevel) {
314	
315	        /** The fixed {@code event} discriminator carried by every emitted event. */
316	        private static final String EVENT_TYPE = "OWNER_CREATED";
317	
318	        /** Shared, thread-safe mapper used only to serialize the event to its JSON form. */
319	        private static final ObjectMapper MAPPER = JsonMapper.builder().build();
320	
321	        /**
322	         * Serializes this event to its compact JSON form
323	         * {@code {seq, ownerId, customerCode, membershipLevel, event}}, with the fields in that order.
324	         *
325	         * @return the event as a JSON object string
326	         */
327	        private String toJson() {
328	            Map<String, Object> fields = new LinkedHashMap<>();
329	            fields.put("seq", this.seq);
330	            fields.put("ownerId", this.ownerId);
331	            fields.put("customerCode", this.customerCode);
332	            fields.put("membershipLevel", this.membershipLevel);
333	            fields.put("event", EVENT_TYPE);
