570	    /**
571	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
572	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
573	     * what gets stored and returned.
574	     *
575	     * @param telephone the raw telephone value from the request
576	     * @return the normalized E.164 telephone number
577	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
578	     */
579	    private String normalizeTelephone(String telephone) {
580	        String e164 = toE164(telephone);
