587	    /**
588	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
589	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
590	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
591	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
592	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
593	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
594	     *
595	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
596	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
597	     *
598	     * @param telephone the raw telephone value, possibly {@code null}
599	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
600	     */
601	    private String toE164(String telephone) {
602	        if (telephone == null) {
603	            return null;
604	        }
605	        String cleaned = telephone.replaceAll("[ \\-()]", "");
606	        String digits;
607	        if (cleaned.startsWith("+")) {
608	            digits = cleaned.substring(1);
609	        } else {
610	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
611	            digits = "61" + national;
612	        }
613	        if (!digits.matches("[0-9]{8,15}")) {
614	            return null;
615	        }
616	        if (!nationalNumberLengthValid(digits)) {
617	            return null;
618	        }
619	        return "+" + digits;
620	    }
621	
622	    /**
623	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
624	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
625	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
626	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
627	     * accepted, leaving only the generic total-length rule to apply.
628	     *
629	     * @param digits the E.164 digits without the leading {@code '+'}
630	     * @return {@code true} if the national-number length matches the country code's requirement
631	     */
632	    private boolean nationalNumberLengthValid(String digits) {
633	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
634	            String code = entry.getKey();
635	            if (digits.startsWith(code)) {
636	                return digits.length() - code.length() == entry.getValue();
637	            }
638	        }
639	        return true;
640	    }
