642	    /**
643	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
644	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
645	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
646	     * returned lower-cased.
647	     *
648	     * @param email the raw email value from the request, possibly {@code null}
649	     * @return the lower-cased email, or {@code null} when none was supplied
650	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
651	     *     its domain is on the disposable-domain blocklist
652	     */
653	    private String normalizeEmail(String email) {
654	        if (!StringUtils.hasText(email)) {
655	            return null;
656	        }
657	        String trimmed = email.trim();
658	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
659	            throw new InvalidOwnerFieldsException(List.of("email"));
660	        }
661	        String normalized = trimmed.toLowerCase(Locale.ROOT);
662	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
663	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
664	            throw new InvalidOwnerFieldsException(List.of("email"));
665	        }
666	        return normalized;
667	    }
