669	    /**
670	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
671	     * This is the single consolidated duplicate check: the identity key
672	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
673	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
674	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
675	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
676	     * but carrying different telephones have different identity keys and are both allowed (the second
677	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
678	     *
679	     * @param owner the owner being created, with its normalized telephone, email and last name set
680	     * @throws DuplicateIdentityException if another owner already has this identity key
681	     */
682	    private void requireUniqueIdentity(Owner owner) {
683	        String identityKey = owner.getIdentityKey();
684	        boolean inUse = this.clinicService.findAllOwners().stream()
685	            .filter(existing -> !existing.isDeleted())
686	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
687	        if (inUse) {
