692	    /**
693	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
694	     * When the computed code is unique it is returned unchanged. When it collides with an existing
695	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
696	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
697	     * so on), and that de-duplicated code is returned.
698	     *
699	     * @param customerCode the freshly computed customer code to de-duplicate
700	     * @return a customer code not held by any existing owner
701	     */
702	    private String deduplicateCustomerCode(String customerCode) {
703	        Set<String> inUse = this.clinicService.findAllOwners().stream()
704	            .map(Owner::getCustomerCode)
705	            .filter(Objects::nonNull)
706	            .collect(Collectors.toSet());
707	        if (!inUse.contains(customerCode)) {
708	            return customerCode;
709	        }
710	        int n = 2;
711	        String candidate;
712	        do {
713	            candidate = customerCode + "-" + n;
714	            n++;
715	        } while (inUse.contains(candidate));
716	        return candidate;
717	    }
