719	    /**
720	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
721	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
722	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
723	     * (both present and equal) while carrying a different identity key. When such an existing owner is
724	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
725	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
726	     * is false and {@code possibleDuplicateOf} is left unset.
727	     *
728	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
729	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
730	     *
731	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
732	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
733	     */
734	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
735	        if (declaredHouseholdMember || owner.getPostcode() == null) {
736	            owner.setPossibleDuplicate(false);
737	            return;
738	        }
739	        String identityKey = owner.getIdentityKey();
740	        String soundex = Soundex.encode(owner.getLastName());
741	        Integer matchId = this.clinicService.findAllOwners().stream()
742	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
743	                && owner.getPostcode().equals(existing.getPostcode())
744	                && !identityKey.equals(existing.getIdentityKey()))
745	            .map(Owner::getId)
746	            .min(Integer::compareTo)
747	            .orElse(null);
748	        owner.setPossibleDuplicate(matchId != null);
749	        owner.setPossibleDuplicateOf(matchId);
750	    }
751	
752	    /**
753	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
754	     * the household - the existing owners that share the deterministic {@code householdId} and the new
755	     * one - so the shared size can be read back from any of them. The count is the number of existing
756	     * members plus the owner being created.
757	     *
758	     * @param owner the owner being created, with its deterministic {@code householdId} already set
759	     */
760	    private void stampHouseholdSize(Owner owner) {
761	        List<Owner> members = householdMembers(owner);
762	        int householdSize = members.size() + 1;
763	        owner.setHouseholdSize(householdSize);
764	        for (Owner member : members) {
765	            member.setHouseholdSize(householdSize);
766	            this.clinicService.saveOwner(member);
767	        }
768	    }
769	
770	    /**
771	     * The existing owners that belong to the same household as the given owner - those that share its
772	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
773	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
774	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
775	     * only live members filter them out themselves.
776	     *
777	     * @param owner the owner being created, with its deterministic {@code householdId} already set
778	     * @return the existing same-household owners
779	     */
780	    private List<Owner> householdMembers(Owner owner) {
781	        String householdId = owner.getHouseholdId();
782	        return this.clinicService.findAllOwners().stream()
783	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
784	            .toList();
785	    }
786	
787	    /**
788	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
789	     * membership level among the existing members of its household - the non-deleted owners that share
790	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
791	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
792	     * has no existing member no cap applies and the level is left untouched.
793	     *
794	     * @param owner the owner being created, with its deterministic {@code householdId} and
795	     *     {@code householdSize} already set
796	     */
797	    private void capMembershipLevelToHousehold(Owner owner) {
798	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
799	            .filter(existing -> !existing.isDeleted())
800	            .mapToInt(Owner::getMembershipLevel)
801	            .max();
802	        if (maxMemberLevel.isEmpty()) {
803	            return;
804	        }
805	        int cap = maxMemberLevel.getAsInt() + 1;
806	        if (owner.getMembershipLevel() > cap) {
807	            owner.setMembershipLevel(cap);
808	        }
809	    }
810	
811	    /**
812	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
813	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
814	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
815	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
816	     * shares a last name and postcode computes the same identifier and therefore the same household.
817	     *
818	     * @param lastName the last name of the household
819	     * @param postcode the postcode of the household, possibly {@code null}
820	     * @return the 12-character upper-case hex household identifier
821	     */
822	    private String computeHouseholdId(String lastName, String postcode) {
823	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
824	        try {
825	            byte[] digest = MessageDigest.getInstance("SHA-256")
826	                .digest(key.getBytes(StandardCharsets.UTF_8));
827	            StringBuilder hex = new StringBuilder(12);
828	            for (int i = 0; i < 6; i++) {
829	                hex.append(String.format("%02X", digest[i]));
830	            }
831	            return hex.toString();
832	        } catch (NoSuchAlgorithmException e) {
833	            throw new IllegalStateException("SHA-256 algorithm not available", e);
834	        }
835	    }
836	
837	    /**
838	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
839	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
840	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
841	     *
842	     * @param value the raw value, possibly {@code null}
843	     * @return the normalized value
844	     */
845	    private String normalizeForHousehold(String value) {
846	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
847	    }
848	
849	    /**
850	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
851	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
852	     * value yields an empty string.
853	     *
854	     * @param value the raw value, possibly {@code null}
855	     * @return the trimmed, whitespace-collapsed value
856	     */
857	    private String collapseWhitespace(String value) {
858	        if (value == null) {
859	            return "";
860	        }
861	        return value.trim().replaceAll("\\s+", " ");
862	    }
863	
864	    /**
865	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
866	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
867	     * is upper-cased, and common street-type abbreviations are expanded as whole words
868	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
869	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
870	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
871	     *
872	     * @param address the raw address value, possibly {@code null}
873	     * @return the normalized address
874	     */
875	    private String normalizeAddress(String address) {
876	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
877	        if (collapsed.isEmpty()) {
878	            return "";
879	        }
880	        String[] tokens = collapsed.split(" ");
881	        StringBuilder normalized = new StringBuilder();
882	        for (int i = 0; i < tokens.length; i++) {
883	            if (i > 0) {
884	                normalized.append(' ');
885	            }
886	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
887	        }
888	        return normalized.toString();
889	    }
890	
891	    /**
892	     * Applies the owner's address from the request, preferring the structured form over the flat one.
893	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
894	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
895	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
896	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
897	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
898	     * the structured address when present, falling back to the flat address.
899	     *
900	     * @param owner the owner being created
901	     * @param ownerFieldsDto the submitted owner fields
902	     */
903	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
904	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
905	        if (StringUtils.hasText(line1)) {
906	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
907	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
908	            owner.setAddressLine1(line1);
909	            owner.setAddressLine2(normalizedLine2);
910	            owner.setAddress(composeAddress(line1, normalizedLine2));
911	        } else {
912	            owner.setAddressLine1(null);
913	            owner.setAddressLine2(null);
914	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
915	        }
916	    }
917	
918	    /**
919	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
920	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
921	     * appended when the second line is present.
922	     *
923	     * @param line1 the normalized first address line
924	     * @param line2 the normalized second address line, or {@code null} when absent
925	     * @return the composed address string
926	     */
927	    private String composeAddress(String line1, String line2) {
928	        return line2 == null ? line1 : line1 + " " + line2;
929	    }
930	
931	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
932	    @Override
933	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
934	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
935	        if (currentOwner == null) {
936	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
937	        }
938	        currentOwner.setAddress(ownerFieldsDto.getAddress());
939	        currentOwner.setCity(ownerFieldsDto.getCity());
940	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
941	        currentOwner.setLastName(ownerFieldsDto.getLastName());
942	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
943	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
944	        this.clinicService.saveOwner(currentOwner);
945	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
946	    }
947	
948	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
949	    @Transactional
950	    @Override
951	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
952	        Owner owner = this.clinicService.findOwnerById(ownerId);
953	        if (owner == null) {
954	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
955	        }
956	        owner.setDeleted(true);
957	        this.clinicService.saveOwner(owner);
958	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
959	    }
960	
961	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
962	    @Override
963	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
964	        Owner owner = this.clinicService.findOwnerById(ownerId);
965	        if (owner == null) {
966	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
967	        }
968	        HttpHeaders headers = new HttpHeaders();
